def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    my_defects = sum(1 for m in my_moves if m == 'D')
    opp_defects = sum(1 for m in opp_moves if m == 'D')
    last_my = my_moves[-1]
    last_opp = opp_moves[-1]

    if n < 4:
        return 'C'

    if opp_defects > n * 0.6:
        return 'D'

    if opp_defects == 0:
        if my_defects < 2:
            return 'D'
        if n > 30:
            return 'D'
        return 'C'

    if opp_defects <= 2:
        return 'C'

    if last_opp == 'D':
        if last_my == 'D' and n >= 2 and opp_moves[-2] == 'C':
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    else:
        if last_my == 'D':
            retaliations = 0
            for i in range(n - 1):
                if my_moves[i] == 'D' and opp_moves[i + 1] == 'D':
                    retaliations += 1
            if retaliations == 0 and n < 80:
                return 'D'
            return 'C'
        return 'C'
